import json,statistics,hashlib
from variants import ARMS
from run import HERE

def main():
 rows=[json.loads((HERE/f'seed-{s}'/f'{a}.json').read_text()) for s in (11,23,37) for a in ARMS]
 for seed in (11,23,37):assert len({r['initial_sha256'] for r in rows if r['seed']==seed})==1
 assert {r['parameters'] for r in rows}=={34479}
 assert len({r['training_excerpt_sha256'] for r in rows})==1
 assert {r['protocol_sha256'] for r in rows}=={hashlib.sha256((HERE/'PROTOCOL.md').read_bytes()).hexdigest()}
 summary={}
 lines=['# CSM-COLLAPSE-004 results','','Twelve matched-parameter mechanistic fits on one authentic 128-target training excerpt. Final endpoint only; no selection by development scores. Each fit sees the same excerpt 256 times (32,768 target instances).','','| Variant | Mean fit NLL ↓ | Mean fit accuracy | Fit criterion passes | Adjacent TRAIN NLL | Exposed DEV NLL |','|---|---:|---:|---:|---:|---:|']
 for a in ARMS:
  rr=[r for r in rows if r['arm']==a];v=dict(fit_nll=statistics.mean(r['fit']['nll'] for r in rr),fit_accuracy=statistics.mean(r['fit']['accuracy'] for r in rr),criterion_passes=sum(r['fit_criterion_passed'] for r in rr),adjacent_nll=statistics.mean(r['adjacent_train']['nll'] for r in rr),dev_nll=statistics.mean(r['exposed_dev']['nll'] for r in rr));summary[a]=v
  lines.append(f"| {a} | {v['fit_nll']:.6f} | {v['fit_accuracy']:.2%} | {v['criterion_passes']}/3 | {v['adjacent_nll']:.6f} | {v['dev_nll']:.6f} |")
 lines+=['','Fit criterion fixed before training: NLL<0.7 and accuracy>=80%. Fitting one real excerpt is a debugging test, not a real-world generalization result.','', '| Seed | Variant | Fit NLL | Accuracy | Space share | Distinct predictions |','|---:|---|---:|---:|---:|---:|']
 for r in rows:
  v=r['fit'];lines.append(f"| {r['seed']} | {r['arm']} | {v['nll']:.6f} | {v['accuracy']:.2%} | {v['space_share']:.2%} | {v['distinct_top1']} |")
 lines+=['','## What was controlled','', 'All variants have 34,479 learned parameters and identical initial arrays per seed, inputs, supervision, optimizer and update budget. Their computation differs; actual FLOPs are not matched. Soft routing changes address/update semantics and removes the original single-slot frame guarantee. Soft admission also removes the exact binary no-write decision at finite logits. The residual readout adds no parameters but changes the information and gradient path. There is no claim of equal-compute architectural superiority.','', 'The hard variant exactly matches the archived baseline in forward values and backward gradients on checked fixtures. Causal-prefix, finite-gradient, initialization/count and independent-stream checks pass for the variants. Checkpoints include model, optimizer, RNG, curves and timing; they support resuming at saved presentation boundaries.','', '## Reproduction','', '`python research/csm_collapse_004/test_contracts.py` checks implementation contracts. `run.py --seed 11` (also 23/37) resumes missing fits and skips completed outputs. For a new fit use a separate source copy without seed output directories. `replay.py` validates all checkpoints and final panel scores without fitting. `frozen_audit.py` audits long-run checkpoints without optimization.','', 'No protected TEST scoring, paid compute, GPU, merge or deployment. The adjacent TRAIN excerpt and exposed DEV are diagnostic transfer checks, not selection signals. The prior long-run findings are preserved unchanged.']
 frozen=json.loads((HERE/'frozen_audit.json').read_text())['rows']
 lines+=['','## Frozen long-run audit','', 'No optimizer updates. Measurements use the same authentic 128-target training excerpt. Proposal saturation is the fraction of pre-tanh activations with magnitude > 3; at this threshold tanh derivative is below 0.01. This correlation is not a causal attribution of collapse. Readout standard deviation is averaged over coordinates across time.','', '| Seed | Long-run arm | Proposal saturation | Readout coordinate std | Frontend gradient norm | Proposal-output gradient norm |','|---:|---|---:|---:|---:|---:|']
 for r in frozen:
  a=r['audit']['activations'];g=r['audit']['gradients'];lines.append(f"| {r['seed']} | {r['arm']} | {a['proposal']['abs_above_3']:.2%} | {a['readout']['mean_coordinate_std']:.6f} | {g['core.frontend.weight']['norm']:.6f} | {g['core.transform.2.weight']['norm']:.6f} |")
 local=json.loads((HERE/'local_context_control.json').read_text())['rows']
 lines+=['','## Post-fit local-context control','', 'A lookup fitted and scored on this same excerpt reaches the following accuracy using only recent bytes. This is a descriptive memorization control, not held-out evaluation or a parameter-matched model. It was added after observing successful fitting.','', '| Context bytes | Unique contexts | Training lookup accuracy | Empirical conditional NLL |','|---:|---:|---:|---:|']
 for r in local:lines.append(f"| {r['context_bytes']} | {r['unique_contexts']} | {r['training_lookup_accuracy']:.2%} | {r['empirical_conditional_nll']:.6f} |")
 lines+=['','The 3-byte lookup already explains 95.31% of training targets. Exceeding this on the same exact inputs requires distinguishing some histories sharing the last 3 bytes, but does not establish generalizable retrieval, record semantics, or compositional reasoning.']
 lines+=['','## Interpretation boundary','', 'The unchanged model passed all three fits, ruling out an unavoidable constant-output limitation on this diagnostic. The frontend residual reached high accuracy earlier and the lowest mean final fitting loss, while soft admission failed in one seed. None establishes adequate capacity for general language modeling: transfer losses remain poor. This study changes learning rate and data repetition relative to LONGBENCH-003; it cannot isolate which caused the earlier collapse. Within this study the four variants have matched learning settings.', '', 'The residual readout changes both the available information and gradient path and the input distribution seen by the output head. Any advantage cannot uniquely identify one of these as the cause. Soft routing changes the forward state dynamics as well as the gradient estimator. Further controlled experiments are needed before selecting a replacement architecture.']
 (HERE/'summary.json').write_text(json.dumps(summary,indent=2)+'\n');(HERE/'README.md').write_text('\n'.join(lines)+'\n');print(json.dumps(summary,indent=2))
if __name__=='__main__':main()
